"/* Modern Task Pane Styles */
:root {
    --primary-color: #2b579a;
    --primary-hover: #1e3f70;
    --secondary-color: #f3f4f6;
    --secondary-hover: #e5e7eb;
    --text-primary: #1f2937;
    --text-secondary: #4b5563;
    --border-color: #e5e7eb;
    --bg-card: #f9fafb;
    --success-bg: #ecfdf5;
    --success-text: #065f46;
    --success-border: #a7f3d0;
    --warning-bg: #fffbeb;
    --warning-text: #92400e;
    --warning-border: #fde68a;
    --error-bg: #fef2f2;
    --error-text: #991b1b;
    --error-border: #fecaca;
    --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--font-family);
    background-color: #ffffff;
    color: var(--text-primary);
    padding: 16px;
    font-size: 13px;
    line-height: 1.5;
}

.container {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

/* Header */
.header {
    display: flex;
    align-items: center;
    gap: 12px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--border-color);
}

.icon-badge {
    width: 40px;
    height: 40px;
    border-radius: 8px;
    background-color: #eff6ff;
    color: var(--primary-color);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.title {
    font-size: 15px;
    font-weight: 600;
    color: var(--text-primary);
}

.subtitle {
    font-size: 12px;
    color: var(--text-secondary);
}

/* Actions */
.actions {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.btn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    width: 100%;
